package dev.veltraph.client.input;
import org.junit.jupiter.api.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
/** Real logical APIs only; no fake canonical Root cause or native history is constructed. */
final class LogicalLockMutationSerializationTest {
 @BeforeEach void reset(){ScriptingInputLock.onRelease(()->{});ScriptingInputLock.releaseAll();}
 @AfterEach void cleanup(){ScriptingInputLock.onRelease(()->{});ScriptingInputLock.releaseAll();}
 @Test void missingCanonicalCauseCannotRetireOrRunCompatibilityCallback(){var calls=new AtomicInteger();ScriptingInputLock.onRelease(calls::incrementAndGet);ScriptingInputLock.acquire("owned");var before=ScriptingInputLock.controlSnapshot();assertFalse(ScriptingInputLock.retireActualRootLogical(before,null));assertTrue(before.current());assertTrue(ScriptingInputLock.isActive());assertEquals("owned",ScriptingInputLock.ownerModuleId());assertEquals(0,calls.get());}
 @Test void actualForeignOwnerAbaInvalidatesOldSnapshotWithoutRebasing(){ScriptingInputLock.acquire("old");var before=ScriptingInputLock.controlSnapshot();ScriptingInputLock.acquire("foreign");ScriptingInputLock.acquire("old");assertFalse(before.current());assertEquals("old",ScriptingInputLock.ownerModuleId());assertTrue(ScriptingInputLock.controlSnapshot().current());}
 @Test void releaseCallbackMayAcquireOnWorkerWithoutHoldingLogicalMutationMonitor(){var workers=Executors.newSingleThreadExecutor();try{ScriptingInputLock.onRelease(()->{try{workers.submit(()->ScriptingInputLock.acquire("worker-owner")).get(2,TimeUnit.SECONDS);}catch(Exception failure){throw new IllegalStateException("Compatibility callback blocked worker logical acquisition",failure);}});ScriptingInputLock.acquire("old");assertDoesNotThrow(ScriptingInputLock::releaseAll);assertTrue(ScriptingInputLock.isActive());assertEquals("worker-owner",ScriptingInputLock.ownerModuleId());assertTrue(ScriptingInputLock.controlSnapshot().current());}finally{workers.shutdownNow();}}
 @Test void synchronousCallbackMayReenterAcquireWithoutOldReleaseOverwritingNewOwner(){ScriptingInputLock.onRelease(()->ScriptingInputLock.acquire("new"));ScriptingInputLock.acquire("old");var before=ScriptingInputLock.controlSnapshot();ScriptingInputLock.releaseAll();assertFalse(before.current());assertTrue(ScriptingInputLock.isActive());assertEquals("new",ScriptingInputLock.ownerModuleId());}
 @Test void enabledActualLoggerMayWaitForWorkerSnapshotWithoutHoldingMutationMonitor(){var previous=dev.veltraph.client.log.VeltraphLog.get();var workers=Executors.newSingleThreadExecutor();var timestamps=new AtomicInteger();try{var logger=new dev.veltraph.client.log.VeltraphLogger(line->{},()->{timestamps.incrementAndGet();try{assertNull(workers.submit(ScriptingInputLock::controlSnapshot).get(2,TimeUnit.SECONDS),"In-flight logical mutation must remain unavailable without blocking worker");return "actual-worker";}catch(Exception failure){throw new IllegalStateException("Enabled logger blocked worker snapshot",failure);}},msg->{});logger.setMode(dev.veltraph.client.log.DebugLogMode.DETAILS);logger.setEnabled(true);dev.veltraph.client.log.VeltraphLog.set(logger);assertDoesNotThrow(()->ScriptingInputLock.acquire("logged"));assertTrue(ScriptingInputLock.controlSnapshot().current());assertDoesNotThrow(ScriptingInputLock::releaseAll);assertEquals(2,timestamps.get());assertFalse(ScriptingInputLock.isActive());assertTrue(ScriptingInputLock.controlSnapshot().current());}finally{dev.veltraph.client.log.VeltraphLog.set(previous);workers.shutdownNow();}}
}
